    private async Task LoadRoadPageDataAsync(CancellationToken token)
    {
        var page = await RoadApi.GetAllAsync(new RoadQueries
        {
            Skip = roadPageIndex * RoadPageSize,
            Take = RoadPageSize,
            SearchTerm = searchTerm
        }, token);
        roads.Clear();
        roads.AddRange(page.Items);
        totalRoadCount = page.TotalCount;
        if (roadPageIndex >= RoadPageCount)
        {
            roadPageIndex = Math.Max(0, RoadPageCount - 1);
            page = await RoadApi.GetAllAsync(new RoadQueries
            {
                Skip = roadPageIndex * RoadPageSize,
                Take = RoadPageSize,
                SearchTerm = searchTerm
            }, token);
            roads.Clear();
            roads.AddRange(page.Items);
            totalRoadCount = page.TotalCount;
        }

    }

    private async Task LoadRoadMapDataAsync(CancellationToken token)
    {
        mapRoads.Clear();
        mapRoads.AddRange(await RoadApi.GetMapAsync(new RoadMapQuery
        {
            SearchTerm = searchTerm,
            Zoom = 9,
            Take = 500
