    private async Task SaveRoadAsync()
    {
        editorError = null;
        isSaving = true;
        try
        {
            if (string.IsNullOrWhiteSpace(editorName))
                throw new FormatException("نام راه یا مسیر الزامی است.");

            var paths = await JS.InvokeAsync<MapPoint[][]>("rmsInterop.getRoadEditorPaths");
            var validPaths = paths.Where(path => path.Length >= 2).ToArray();
            if (validPaths.Length == 0)
                throw new FormatException("حداقل یک مسیر با دو نقطه روی نقشه مشخص کنید.");

            var geometryFactory = new GeometryFactory(new PrecisionModel(), 4326);
            var route = geometryFactory.CreateMultiLineString(validPaths
                .Select(path => geometryFactory.CreateLineString(path
                    .Select(point => new Coordinate(point.Longitude, point.Latitude))
                    .ToArray()))
                .ToArray());
            var interiorPoint = route.InteriorPoint;
            interiorPoint.SRID = route.SRID;

            if (editingRoadId.HasValue)
            {
                await RoadApi.UpdateAsync(editingRoadId.Value, new UpdateRoadCommand
                {
                    Id = editingRoadId.Value,
                    Name = editorName.Trim(),
                    Boundary = route,
                    Centroid = interiorPoint
                });
                successMessage = "مسیر با موفقیت ویرایش شد.";
            }
            else
            {
                await RoadApi.CreateAsync(new CreateRoadCommand
                {
                    Name = editorName.Trim(),
                    Boundary = route,
                    Centroid = interiorPoint
                });
                successMessage = "مسیر با موفقیت ثبت شد.";
            }

            editorOpen = false;
            await JS.InvokeVoidAsync("rmsInterop.disposeRoadEditorMap");
            await LoadAsync();
        }
        catch (Exception exception) when (exception is ApiClientException or HttpRequestException or FormatException)
        {
            editorError = ErrorMessage(exception, "ذخیره مسیر با خطا مواجه شد.");
        }
        finally
        {
            isSaving = false;
        }
    }

